<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateSnippet\Application\Usecase\Retrieve;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\TemplateSnippetRef;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Service\Visibility\TemplateSnippetVisibilityService;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Gateway\TemplateSnippetReadGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateSnippetRetrieveUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly TemplateSnippetVisibilityService $visibility,
        private readonly TemplateSnippetReadGateway $reader
    ) {
    }

    public function allowRetrieve(?TemplateSnippetRef $ref = null): Allow
    {
        $this->logDebug("Check allow of retrieve usecase for Template snippet");
        $span = $this->startSpan("Check allow of retrieve usecase for Template snippet");
        try {
            $result = $this->dispatcher->dispatch(new TemplateSnippetRetrieveAllowDecision(Allow::allowed('retrieve', 'Allowed to retrieve by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function hiddenFields(?TemplateSnippetRef $ref = null): array
    {
        $this->logDebug("Check hidden fields usecase for Template snippet");
        $span = $this->startSpan("Check hidden fields usecase for Template snippet");
        try {
            return $this->visibility->fieldsToHide($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieve(string $uid): TemplateSnippetRetrieveResult
    {
        $this->logDebug("Run retrieve usecase for Template snippet");
        $span = $this->startSpan("Run retrieve usecase for Template snippet");
        try {
            $ref = new TemplateSnippetRef($uid);
            $allow = $this->allowRetrieve($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to retrieve Template snippet');
            }
            if (!$result = $this->visibility->retrieveVisible($ref)) {
                throw new NotFoundException($uid);
            }
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new TemplateSnippetRetrieveResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
